  ["24b0fcbb81e8495d"] = { "「Darnassae?」\n\nナイトエルフのドルイドは期待するようにあなたを見つめるが、言葉で意思を通わせることができないのは明らかだ。それでもめげずに、彼女は自分を指さして微笑む。次にあなたを指さして、もう一度微笑む。最後に、北へ続く道の先を何度も指し示す。\n\nもしかすると、この道の先にもっと話のできるドルイドがいると伝えようとしているのかもしれない。", "." },
  ["24b2b7591aa9cf7b"] = { "%sは{name}の後についていった。", "." },
  ["24bef9ec5a364a44"] = { "私と同志たちは、知る限り最も致死性の高い物質を集め、その効果を敵で試している。必要なものがすべて揃ったら、この世界がかつて見たこともないような疫病を醸造してやろう。", "." },
  ["24c0c1adac216ce8"] = { "LuciusはRavenholdt Manorの古くからの信頼できる友人です――彼とは話すことがたくさんあります。私の助けや助言が必要なら、Lakeshireの船着き場で私を探してください。", "." },
  ["24c652dba5f9b8e5"] = { "さて友よ、君は多くの人が夢見るだけの高みにたどり着いた。おめでとう！では、前置きはこれくらいにして、最後の授業の時間だ！", "." },
  ["24c8940da641e793"] = { "余っている物資はたくさんあるが、Field of Strifeへ攻撃部隊を送り込むにはまだ足りない。", "." },
  ["24d069203771ef41"] = { "この地域はいまだにScourgeの疫病に支配されている。疫病を改変してやつらに効くようにするまでには、まだ長い道のりがある。必要な資源を集めて、戦いに協力してくれ!", "." },
  ["24d30eed1f16d15c"] = { "闇の勢力が我らの国境に迫り、古の穢れが再び現れ、新たな邪悪がこの地の繊細な均衡を覆そうとしています。このような闇の時代には、私たち皆が警戒を怠ってはなりません。", "." },
  ["24d406484e28a8af"] = { "Ishnu-dal-dieb、{name}。知識を求めてここへ来たのですか?", "." },
